function Main(input) {
  input = myconv(input,3);
  input.shift();
  var output = 0;
  for(var i = 0; i < input.length; i++){
    var A = parseInt(input[i].split(" ")[0]);
	var B = parseInt(input[i].split(" ")[1]);
    if(A < B){
       output += B;
    }
  }
  myout(output);
